const express = require("express");
const router = express.Router();
const db = require("../db");
const jwt = require("jsonwebtoken");

// AUTH MIDDLEWARE
function auth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ message: "No token" });

  const token = authHeader.split(" ")[1];
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET || "secret");
    next();
  } catch (e) {
    return res.status(401).json({ message: "Invalid token" });
  }
}

// -------------------------------------------
//  HELPERS
// -------------------------------------------
function calculateBadge(points) {
  if (points >= 300) return "Gold";
  if (points >= 100) return "Silver";
  return "Bronze";
}

// -------------------------------------------
//  GET USER ACHIEVEMENT + BADGES
// -------------------------------------------
router.get("/achievement", auth, async (req, res) => {
  try {
    const [rows] = await db.query(
      "SELECT points FROM achievements WHERE user_id = ?",
      [req.user.id]
    );

    const points = rows[0]?.points || 0;

    res.json({
      points,
      badge: calculateBadge(points),
    });
  } catch (err) {
    console.log(err);
    res.status(500).json({ message: "Error fetching achievement" });
  }
});

// -------------------------------------------
//  ADD DONATION POINTS
// -------------------------------------------
router.post("/donate", auth, async (req, res) => {
  const { amount } = req.body;

  if (!amount || amount <= 0)
    return res.status(400).json({ message: "Invalid amount" });

  try {
    // Add donation to DB
    await db.query(
      "INSERT INTO donations (user_id, amount, ngo_id) VALUES (?, ?, ?)",
      [req.user.id, amount, req.body.ngo_id || null]
    );

    // Update points
    await db.query(
      "INSERT INTO achievements (user_id, points) VALUES (?, ?) ON DUPLICATE KEY UPDATE points = points + ?",
      [req.user.id, amount, amount]
    );

    // Fetch updated points
    const [rows] = await db.query(
      "SELECT points FROM achievements WHERE user_id = ?",
      [req.user.id]
    );

    const points = rows[0].points;

    res.json({
      message: "Donation recorded",
      points,
      badge: calculateBadge(points),
    });
  } catch (e) {
    console.log(e);
    res.status(500).json({ message: "Error donating" });
  }
});

// -------------------------------------------
//  ADD PARTICIPATION POINTS
// -------------------------------------------
router.post("/participate", auth, async (req, res) => {
  try {
    // Store participation record
    await db.query(
      "INSERT INTO participation (user_id, event_id) VALUES (?, ?)",
      [req.user.id, req.body.event_id || null]
    );

    const PARTICIPATION_POINTS = 10;

    // Update points
    await db.query(
      "INSERT INTO achievements (user_id, points) VALUES (?, ?) ON DUPLICATE KEY UPDATE points = points + ?",
      [req.user.id, PARTICIPATION_POINTS, PARTICIPATION_POINTS]
    );

    // Fetch updated
    const [rows] = await db.query(
      "SELECT points FROM achievements WHERE user_id = ?",
      [req.user.id]
    );

    const points = rows[0].points;

    res.json({
      message: "Participation added",
      points,
      badge: calculateBadge(points),
    });
  } catch (e) {
    console.log(e);
    res.status(500).json({ message: "Error adding participation" });
  }
});

// EXPORT ROUTER
module.exports = router;
